function cinemaCurrentTime(){const v=$('#cinVideo');if(v)return Math.max(0,Number(v.currentTime)||0);const s=cinemaSession();return Math.max(0,Number(s&&s.progress)||0);}
function cinemaDuration(){const v=$('#cinVideo');if(v&&Number.isFinite(v.duration))return Math.max(0,v.duration);const s=cinemaSession();return Math.max(0,Number(s&&s.duration)||Number(_cin.videoInfo&&_cin.videoInfo.duration)||0);}
