function cinemaMediaToggle(open){_cin.mediaOpen=open!==false;const bar=$('#cinMediaControls'),stage=$('#cinStage');if(bar)bar.classList.toggle('hidden',!_cin.mediaOpen);if(stage)stage.classList.toggle('media-hidden',!_cin.mediaOpen);}
function cinemaSyncMediaControls(){const v=$('#cinVideo'),play=$('#cinPlayBtn'),seek=$('#cinSeek'),time=$('#cinTime');if(!v&&!_cin.provider)return;const duration=cinemaDuration(),current=cinemaCurrentTime(),paused=v?!!v.paused:!!_cin.externalPaused;if(play){play.textContent=paused?'▶':'❚❚';play.setAttribute('aria-label',paused?'播放':'暂停');play.disabled=_cin.provider==='bilibili';}if(seek&&!seek._dragging){seek.value=duration?String(Math.round(current/duration*1000)):'0';seek.disabled=_cin.provider==='bilibili'||!duration;}if(time)time.textContent=_cin.provider==='bilibili'?'使用播放器内控制':cinemaFmt(current)+' / '+cinemaFmt(duration);}
