function cinemaVideoTick(){const v=$('#cinVideo'),s=cinemaSession();if(!v||!s)return;if(cinemaAsrGuardPlayback(v))return;s.progress=v.currentTime||0;s.duration=Number.isFinite(v.duration)?v.duration:s.duration;s.updatedAt=Date.now();cinemaUpdateSubtitle();cinemaSyncMediaControls();if(Date.now()-_cin.lastSaveAt>5000)cinemaSaveProgress(false);const cue=cinemaCueAt(v.currentTime||0),set=cinemaInit().settings,vi=Math.max(30,+set.visionInterval||150);let next=Number(s.nextVisionAt)||0;if(set.visionEnabled&&set.autoVision&&!next)next=cinemaVisionResetTimer(s,v.currentTime||0);if(set.visionEnabled&&set.autoVision&&!v.paused&&!_cin.visionBusy&&next>0&&v.currentTime>=next){s.nextVisionAt=(v.currentTime||0)+vi;save();cinemaAnalyzeFrame(null,true,{interval:true});}const cueKey=cue?(Math.round(cue.start*10)+'|'+cue.text):'';if(cue&&cueKey!==s.lastAutoCue&&cinemaCanAutoSpeak(s)&&!v.paused&&!_cin.busy&&(v.currentTime||0)>20&&(v.currentTime-(s.lastAuto||0)>cinemaAutoGap())){s.lastAuto=v.currentTime;s.lastAutoCue=cueKey;save();cinemaRoleReply('当前刚播放到的台词是：“'+cue.text+'”。只根据截至当前进度已经出现的内容和你的真实性格，判断这句是否真的触动你、让你想讨论或表达感受；绝对不能引用后面的台词或剧情。真有感触就说一句很短的自然反应；没有明显感触只输出 [保持安静]。',true,{allowSilence:true});}}
