function cinemaUpdateSubtitle(){const v=$('#cinVideo'),sub=$('#cinSub'),status=$('#cinContextStatus');if(!v&&!_cin.provider)return;const cue=cinemaCueAt(cinemaCurrentTime());if(sub){sub.textContent=cue&&cue.source!=='speech'?cue.text:'';sub.classList.toggle('show',!!(cue&&cue.source!=='speech'));}if(status&&!_cin.extracting){if(Date.now()<Number(_cin.statusLockUntil||0))return;status.classList.toggle('working',!!_cin.visionBusy);status.classList.remove('ready','error');status.textContent=_cin.visionBusy?'正在理解当前画面…':(_cin.cues.length||(cinemaSession()&&cinemaSession().sceneDesc))?'':_cin.provider?'官方播放器已连接 · 可导入字幕':'尚未理解画面 · 可提取字幕或识图';}}
function cinemaClearShots(){clearTimeout(_cin.shootTimer);clearTimeout(_cin.voiceSubTimer);_cin.shootTimer=null;_cin.voiceSubTimer=null;_cin.shootQueue=[];_cin.shootEpoch=(_cin.shootEpoch||0)+1;const end=_cin.shootResolve;_cin.shootResolve=null;if(end)try{end();}catch(_){}_cin.shootBusy=false;if(_cin.shootNode&&_cin.shootNode.remove)try{_cin.shootNode.remove();}catch(_){}_cin.shootNode=null;const dm=$('#cinDanmaku'),sub=$('#cinVoiceSub');if(dm)dm.innerHTML='';if(sub)sub.classList.remove('show','mine','role');}
function cinemaShotMs(text,mode){const lines=String(text||'').split(/\n+/),longest=Math.max(1,...lines.map(x=>[...x].length)),total=[...String(text||'')].length;if(mode==='subtitle')return Math.max(3000,Math.min(8000,1400+total*105));return Math.max(5500,Math.min(9000,3900+longest*70+Math.max(0,lines.length-1)*650));}
function cinemaShowShot(who,text){return new Promise(resolve=>{const mode=cinemaCommentDisplay(),ms=cinemaCaptionDuration(text,mode);let done=false;const finish=()=>{if(done)return;done=true;if(_cin.shootResolve===finish)_cin.shootResolve=null;clearTimeout(_cin.shootTimer);_cin.shootTimer=null;if(_cin.shootNode&&_cin.shootNode.remove)try{_cin.shootNode.remove();}catch(_){}_cin.shootNode=null;resolve();};_cin.shootResolve=finish;if(mode==='subtitle'){cinemaShowDialogueSubtitle(who,text,ms);_cin.shootTimer=setTimeout(finish,ms+80);return;}const box=$('#cinDanmaku');if(!box){finish();return;}box.innerHTML='';const d=document.createElement('div');d.className='cin-barrage '+(who==='me'?'mine':'role')+' glide';d.textContent=String(text||'').trim();d.style.top='28%';d.style.animationDuration=(ms/1000)+'s';d.addEventListener('animationend',finish,{once:true});box.appendChild(d);_cin.shootNode=d;_cin.lane++;_cin.shootTimer=setTimeout(finish,ms+400);});}
