function cinemaAddItem(who,text,opt){const s=cinemaSession();if(!s||!text)return null;const item={who,text:String(text).slice(0,240),time:Date.now(),at:s.kind==='video'?cinemaCurrentTime():0,page:s.page||0};s.items=s.items||[];s.items.push(item);if(s.items.length>140)s.items=s.items.slice(-140);s.updatedAt=Date.now();cinemaMirrorToWechat(s,who,item.text);save();cinemaAppendLog(item);cinemaShoot(who,opt&&opt.shootText||item.text,opt);return item;}
function cinemaRoleContext(s){if(s.kind==='book'){const i=Math.max(0,Math.min(s.page||0,_cin.bookPages.length-1)),prev=i?_cin.bookPages[i-1].slice(-360):'';return '当前读到第'+(i+1)+'/'+_cin.bookPages.length+'页。\n'+(prev?'上一页结尾：'+prev+'\n':'')+'当前页正文：'+(_cin.bookPages[i]||'').slice(0,1800);}const t=cinemaCurrentTime(),subs=cinemaSubtitleContext(t),cue=cinemaCueAt(t),source=_cin.provider?cinemaPlatformName(_cin.provider)+'官方播放器。':'';return source+'当前播放时间 '+cinemaFmt(t)+' / '+cinemaFmt(s.duration||0)+'。\n'+(cue?'当前屏幕字幕：'+cue.text+'\n':'')+(subs?'截至此刻已经出现的字幕（绝对不要使用更晚内容）：\n'+subs:'')+(!subs?'目前没有可用字幕，只知道片名；不要假装知道具体剧情。':'')+(s.sceneDesc&&Math.abs(t-(s.sceneAt||0))<180?'\n当前画面理解：'+s.sceneDesc:'');}
function cinemaVoiceRule(c,count){const lang=cinemaVoiceLang(c),name={yue:'粤语',en:'英语',ja:'日语',ko:'韩语',fr:'法语',de:'德语',ru:'俄语'}[lang],n=Math.max(1,+count||1);if(!name)return'\n# 本场角色语音语言\n使用自然中文，每条单独一行。';const yue=lang==='yue',example=yue?'呢幕真係幾好睇。\n（这一幕真的挺好看。）':lang==='ja'?'このシーン、すごく好き。\n（我很喜欢这一幕。）':lang==='ko'?'이 장면 정말 좋아.\n（我很喜欢这一幕。）':lang==='fr'?"J’aime beaucoup cette scène.\n（我很喜欢这一幕。）":lang==='de'?'Diese Szene gefällt mir sehr.\n（我很喜欢这一幕。）':lang==='ru'?'Мне очень нравится эта сцена.\n（我很喜欢这一幕。）':'I like this scene.\n（我喜欢这一幕。）';return'\n# 本场角色语音语言\n每条先用'+name+'写真正说出口的一句，下一行用全角括号写准确的普通话中文翻译；共严格输出 '+n+' 组，每组两行，组与组之间换行。例如：\n'+example+'\n'+(yue?'粤语原文必须使用自然地道的粤语口语和粤语用字，不能改写成普通话句子；':'不要把中文夹进外语原文；')+'不要遗漏翻译。';}
function cinemaRoleSystem(c,s,count){const n=Math.max(1,+count||1),past=topSummaries(c.summaries||[],8).map(x=>'· '+summaryCleanText(c,x.text)).join('\n'),vision=cinemaInit().settings.visionByRole&&s.kind==='video'?'\n如果现有字幕确实不足、必须看当前画面才能回答，你可以只输出 [识别画面]；系统识别后会让你重新回答。不要随便调用。':'';return personaPin(c)+'\n角色核心设定：'+(c.persona||'按既有性格自然相处')+'\n说话习惯：'+traitDesc(c)+rolePriorityPrompt()+(past?'\n你们已有的长期记忆：\n'+past:'')+'\n\n# 放映室同屏陪伴\n你正和'+summaryUserLabel(c)+'在“放映室”一起'+(s.kind==='book'?'读':'看')+'《'+s.title+'》。只允许依据给你的【已看到/已读到】内容回应，严禁引用后面的剧情、常识里的结局或假装看到未提供的画面。像真人同屏时发弹幕一样自然回应：本次严格回复 '+n+' 条，每条都是独立短句，中文或粤语每条不超过28字，其他语言每条不超过12个词；严格按要求的条数输出，不合并成长段。保持角色自己的性格与称呼。只能输出要说的话；不要动作描写、第三人称叙述、括号舞台说明、心情标签、分析过程或“作为AI”。'+vision+cinemaVoiceRule(c,n);}
function cinemaCleanRoleText(raw){let t=cleanReply(raw).replace(/^[\s「『“"]+|[」』”"]+$/g,'').replace(/^\s*[\*（(【\[].{0,32}[\*）)】\]]\s*/,'').replace(/\n+/g,' ').trim();return Array.from(t).slice(0,90).join('');}
function cinemaOneSentence(text,limit){let s=String(text||'').replace(/\s+/g,' ').trim(),m=s.match(/^.*?(?:[。！？]|[.!?](?=\s|$))/);if(m)s=m[0];return s.slice(0,limit||80).trim();}
function cinemaParseRolePayloads(raw,c,count){const lang=cinemaVoiceLang(c),n=Math.max(1,Math.min(5,+count||1)),clean=cleanReply(raw),out=[];if(lang==='zh'){const parts=[];clean.split(/\n+/).forEach(line=>{const t=line.replace(/^[\s\-*\d.、]+/,'').replace(/^[「『“"]+|[」』”"]+$/g,'').trim();if(!t||/^\[(?:识别画面|查看画面)\]$/.test(t))return;const hits=t.match(/[^。！？.!?]+[。！？.!?]?/g)||[t];hits.forEach(v=>{v=cinemaOneSentence(v,64);if(v)parts.push(v);});});parts.slice(0,n).forEach(text=>out.push({spoken:text,translation:'',display:text,valid:true}));return out;}const lines=clean.split(/\n+/).map(x=>x.trim()).filter(x=>x&&!/^\[(?:识别画面|查看画面)\]$/.test(x)),code={yue:'粤',en:'英',ja:'日',ko:'韩'}[lang];for(let i=0;i<lines.length&&out.length<n;i++){if(/^[（(].+[）)]$/.test(lines[i]))continue;const spoken=cinemaOneSentence(lines[i].replace(/^[\s\-*\d.、]+/,'').replace(/^[「『“"]+|[」』”"]+$/g,'').trim(),96),next=lines[i+1],translation=cinemaOneSentence(next&&/^[（(].+[）)]$/.test(next)?next.replace(/^[（(]|[）)]$/g,'').trim():'',64);if(translation)i++;if(spoken)out.push({spoken,translation,display:spoken+(translation?'\n'+translation:''),valid:!!(translation&&hasForeign(spoken,code))});}return out;}
function cinemaParseRolePayload(raw,c){return cinemaParseRolePayloads(raw,c,1)[0]||{spoken:'',translation:'',display:'',valid:false};}
async function cinemaRoleReply(reason,automatic,opt){
  opt=opt||{};
  const s=cinemaSession(),c=s&&getC(s.cid);
  if(!s||!c||_cin.busy)return;
  _cin.busy=true;
  const token=_cin.token,send=$('.cin-send'),count=automatic?1:cinemaRandomReplyCount(),max=Math.min(620,140*count);
  if(send)send.disabled=true;
  try{
    const recent=(s.items||[]).slice(-(cinemaContextRounds()*2)).map(x=>(x.who==='me'?summaryUserLabel(c):c.name)+'：'+x.text).join('\n');
    const makePrompt=()=>cinemaRoleContext(s)+'\n\n最近同屏对话：\n'+(recent||'（还没有）')+'\n\n现在的要求：'+reason;
    const sys=cinemaRoleSystem(c,s,count)+(opt.allowSilence?'\n这是角色自行决定是否主动说话的时刻；如果按你的性格并没有明显感触，必须只输出 [保持安静]，不要硬凑反应。':'');
    let raw=await chatAPI([{role:'system',content:sys},{role:'user',content:makePrompt()}],{max,temp:.68});
    if(token!==_cin.token||cinemaSession()!==s)return;
    if(opt.allowSilence&&/^\s*\[(?:保持安静|不说话)\]\s*$/.test(cleanReply(raw)))return;
    if(/^\s*\[(?:识别画面|查看画面)\]\s*$/.test(cleanReply(raw))&&cinemaInit().settings.visionByRole){
      const ok=await cinemaAnalyzeFrame(null,true,{notice:true});
      if(ok)raw=await chatAPI([{role:'system',content:sys.replace(/\n如果现有字幕[\s\S]*?不要随便调用。/, '')},{role:'user',content:makePrompt()+'\n\n系统已经补充了当前画面理解，现在直接回应。'}],{max,temp:.65});
    }
    if(token!==_cin.token||cinemaSession()!==s)return;
    if(opt.allowSilence&&/^\s*\[(?:保持安静|不说话)\]\s*$/.test(cleanReply(raw)))return;
    let outs=cinemaParseRolePayloads(raw,c,count);
    if(cinemaVoiceLang(c)!=='zh'&&(outs.length<count||outs.some(x=>!x.valid))){
      raw=await chatAPI([{role:'system',content:sys},{role:'user',content:makePrompt()+'\n\n上一版语言格式或条数不合格，请严格按每条“目标语言原文一行，下一行（普通话中文翻译）”，共 '+count+' 组重写。'}],{max,temp:.5});
      if(token!==_cin.token||cinemaSession()!==s)return;
      if(opt.allowSilence&&/^\s*\[(?:保持安静|不说话)\]\s*$/.test(cleanReply(raw)))return;
      outs=cinemaParseRolePayloads(raw,c,count);
    }
    outs=outs.filter(x=>x.spoken).slice(0,count);
    const visionResponse=/^针对系统刚识别到的当前画面/.test(String(reason||''));
    if(automatic&&outs.length&&opt.countActive!==false&&!visionResponse){s.autoCount=(s.autoCount||0)+1;save();}
    const set=cinemaInit().settings,voiceOn=s.kind==='book'?set.bookVoice:set.voiceComment;
    outs.forEach(out=>cinemaAddItem('role',out.display||out.spoken,{shootText:out.display||out.spoken,speakText:voiceOn?out.spoken:'',speaker:voiceOn?c:null}));
  }catch(e){if(!automatic)toast((e&&e.message)||'角色暂时没有接上话');}
  finally{if(token===_cin.token)_cin.busy=false;if(send&&send.isConnected)send.disabled=false;if(!_cin.shootBusy&&!_cin.shootQueue.length)cinemaMicResumeVideo();}
}
function cinemaQuestionNeedsVision(text){return /[?？]|(?:谁|什么|怎么|怎样|为什么|哪里|哪儿|哪个|这是谁|这是|画面|屏幕|长什么|在干嘛|发生了什么|看见|看到)/.test(String(text||''));}
async function cinemaSend(kind){const id=kind==='book'?'cinBookInput':'cinInput',inp=$('#'+id),text=inp&&inp.value.trim(),s=cinemaSession(),token=_cin.token;if(!text||_cin.busy||!s)return;inp.value='';cinemaAddItem('me',text);if(kind==='video'&&cinemaInit().settings.visionOnAsk&&cinemaQuestionNeedsVision(text)&&cinemaVisionConfigured())await cinemaAnalyzeFrame(null,true,{silentReply:true});if(token!==_cin.token||cinemaSession()!==s)return;cinemaRoleReply('回应'+summaryUserLabel(cinemaRole())+'刚发的这句话。若对方问剧情，只依据当前上下文回答；不知道就自然承认此刻还看不出来。',false);}
