function cinemaMicProtectVideo(){const v=$('#cinVideo');if(_cin.micKind!=='video'||!_cin.micKeepVideoPlaying||!v||!v.isConnected||!v.paused||v.ended||_cin.asrGuardPaused||_cin.extracting||(typeof document!=='undefined'&&document.hidden))return false;const token=Number(_cin.micVideoPlayToken||0)+1;_cin.micVideoPlayToken=token;[0,120,360,760].forEach(delay=>setTimeout(()=>{if(token!==_cin.micVideoPlayToken||_cin.micKind!=='video'||!_cin.micKeepVideoPlaying||!v.isConnected||!v.paused||v.ended||_cin.asrGuardPaused||_cin.extracting||(typeof document!=='undefined'&&document.hidden))return;const p=v.play();if(p&&typeof p.catch==='function')p.catch(()=>{});},delay));return true;}
function cinemaMicResumeVideo(){const resume=!!_cin.micResumeVideo,v=$('#cinVideo');_cin.micResumeVideo=false;if(resume&&v&&v.isConnected){const p=v.play();if(p&&typeof p.catch==='function')p.catch(()=>{});}cinemaMicProtectVideo();}
function cinemaMicRestart(){if(!_cin.micKind||!_cin.micSR)return;try{_cin.micSR.start();cinemaMicProtectVideo();}catch(_){} }
function cinemaMicStop(notice){const kind=_cin.micKind,sr=_cin.micSR;_cin.micKind='';_cin.micBusy=false;_cin.micSR=null;_cin.micIgnoreUntil=0;_cin.micKeepVideoPlaying=false;_cin.micVideoPlayToken=Number(_cin.micVideoPlayToken||0)+1;if(sr)try{sr.onend=null;sr.onresult=null;sr.onerror=null;sr.stop();}catch(_){}if(kind)cinemaMicPaint(kind,'idle');cinemaMicResumeVideo();if(notice)toast('持续话筒已关闭');}
function cinemaMicHeard(kind,text){text=String(text||'').trim();if(!text||kind!==_cin.micKind||_cin.busy||_cin.shootBusy)return;const inp=$(kind==='book'?'#cinBookInput':'#cinInput');if(!inp)return;clearTimeout(_cin.voiceSubTimer);const sub=$('#cinVoiceSub');if(sub)sub.classList.remove('show','mine','role');inp.value=text;cinemaSend(kind);}
function cinemaMicToggle(kind){kind=kind==='book'?'book':'video';if(_cin.micKind){if(_cin.micKind!==kind)return toast('请先关闭另一个持续话筒');cinemaMicStop(true);return;}if(_rec)return toast('另一个录音正在使用麦克风');const sr=makeSR();if(!sr){toast('当前浏览器不支持持续语音识别，请使用系统浏览器并允许麦克风权限');return;}const video=kind==='video'?$('#cinVideo'):null;_cin.micKind=kind;_cin.micSR=sr;_cin.micBusy=false;_cin.micKeepVideoPlaying=!!(video&&!video.paused&&!video.ended);cinemaMicPaint(kind,'recording');sr.onresult=ev=>{if(kind!==_cin.micKind||_cin.busy||_cin.shootBusy||Date.now()<(_cin.micIgnoreUntil||0))return;let finalText='',interim='';for(let i=ev.resultIndex;i<ev.results.length;i++){const t=String(ev.results[i][0].transcript||'').trim();if(ev.results[i].isFinal)finalText+=t;else interim+=t;}if(finalText)cinemaMicHeard(kind,finalText);else if(interim)cinemaShowDialogueSubtitle('me',interim,1200);};sr.onerror=e=>{if(kind!==_cin.micKind)return;if(e&&/not-allowed|service-not-allowed|audio-capture/.test(e.error||'')){cinemaMicStop(false);toast('麦克风没有获得权限，请在系统设置里允许');return;}if(e&&/no-speech|aborted|network/.test(e.error||''))setTimeout(cinemaMicRestart,500);};sr.onend=()=>{if(kind===_cin.micKind)setTimeout(cinemaMicRestart,300);};try{sr.start();cinemaMicProtectVideo();if(kind==='video')cinemaSetStatus('持续话筒已开启 · 直接说话','ready');toast('持续话筒已开启，停顿后会自动发送');}catch(_){cinemaMicStop(false);toast('持续话筒启动失败，请检查麦克风权限');}}
function cinemaMicCancel(){cinemaMicStop(false);}
function cinemaToggleDanmaku(){const mode=cinemaCommentDisplay(),speed=cinemaCaptionSpeed();openModal(`<h3>角色文字显示方式</h3><div class="hint">弹幕和底部字幕只会开启一种。你的文字和角色文字统一使用当前选择。</div><div class="btns"><button class="btn ${mode==='barrage'?'p':'g'}" onclick="cinemaCommentDisplaySave('barrage')">弹幕模式</button><button class="btn ${mode==='subtitle'?'p':'g'}" onclick="cinemaCommentDisplaySave('subtitle')">底部字幕模式</button></div><h3 style="margin-top:18px">字幕显示速度</h3><div class="hint">双方统一按文字长度计算速度，不再让角色跟随语音时长突然飞快；当前一句不会被截断。</div><div class="btns"><button class="btn ${speed==='faster'?'p':'g'}" onclick="cinemaCaptionSpeedSave('faster')">更快</button><button class="btn ${speed==='base'?'p':'g'}" onclick="cinemaCaptionSpeedSave('base')">快</button><button class="btn ${speed==='slower'?'p':'g'}" onclick="cinemaCaptionSpeedSave('slower')">标准</button><button class="btn ${speed==='slowest'?'p':'g'}" onclick="cinemaCaptionSpeedSave('slowest')">更慢</button></div>`);}
