function cinemaCompanionMenu(){const set=cinemaInit().settings,mode=cinemaCompanionMode(),limit=cinemaAutoLimit();openModal(`<h3>陪伴活跃度</h3><div class="hint">看剧和书架共用这套设置。“安静陪伴”会停止根据字幕和翻页随意插话；但如果你另行开启了定时画面识别，识别成功后角色仍会立即回应这一帧。</div><div class="field"><label>陪伴模式</label><select id="cinCompanionMode"><option value="quiet" ${mode==='quiet'?'selected':''}>安静陪伴 · 不根据字幕随意插话</option><option value="soft" ${mode==='soft'?'selected':''}>轻声陪伴 · 偶尔主动说一句</option><option value="lively" ${mode==='lively'?'selected':''}>活跃陪伴 · 更常接话但不刷屏</option></select></div><div class="field"><label>整场主动消息上限</label><select id="cinAutoLimit">${[0,1,2,3,4,5,6,8,10,12,15,20].map(v=>`<option value="${v}" ${v===limit?'selected':''}>${v} 条${v===0?'（不主动）':''}</option>`).join('')}</select></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="cinemaCompanionSave()">保存</button></div>`);}
function cinemaCompanionSave(){const set=cinemaInit().settings,mode=((($('#cinCompanionMode')||{}).value)||'soft');set.companionMode=['quiet','soft','lively'].includes(mode)?mode:'soft';set.autoLimit=Math.max(0,Math.min(20,+((($('#cinAutoLimit')||{}).value)||4)));set.autoComment=set.companionMode!=='quiet';save();closeModal();['#cinAutoBtn','#cinBookCompanionBtn'].forEach(sel=>{const b=$(sel);if(!b)return;b.classList.toggle('on',set.companionMode!=='quiet');const t=b.querySelector('span');if(t)t.textContent=cinemaCompanionLabel()+' · '+cinemaAutoLimit()+'条/场';});toast('已设为'+cinemaCompanionLabel()+'，整场最多主动 '+cinemaAutoLimit()+' 条');}
