function cinemaApplyVisionSubtitle(text,at){text=String(text||'').replace(/\s+/g,' ').trim().slice(0,240);if(!text)return 0;at=Math.max(0,Number(at)||0);_cin.cues=_cin.cues.filter(x=>x&&x.source!=='vision-subtitle');_cin.cues.push({start:_cin.provider?0:Math.max(0,at-.6),end:_cin.provider?86400:at+9,text,source:'vision-subtitle'});_cin.cues.sort((a,b)=>a.start-b.start);const s=cinemaSession();if(s){s.visibleSubtitle=text;s.visibleSubtitleAt=at;s.updatedAt=Date.now();save();}cinemaUpdateSubtitle();return 1;}
function cinemaCropPlatformFrame(data){return new Promise(resolve=>{const img=new Image();img.onload=()=>{try{const node=document.querySelector('.cin-platform-frame'),rect=node&&node.getBoundingClientRect();if(!rect||rect.width<80||rect.height<45)return resolve(data);const screenW=Math.max(1,Number(window.screen&&window.screen.width)||window.innerWidth||rect.right),screenH=Math.max(1,Number(window.screen&&window.screen.height)||window.innerHeight||rect.bottom),viewH=Math.max(1,window.innerHeight||screenH),topInset=Math.max(0,screenH-viewH),sx=img.naturalWidth/screenW,sy=img.naturalHeight/screenH,padX=rect.width*.015,padY=rect.height*.025,left=Math.max(0,Math.floor((rect.left-padX)*sx)),top=Math.max(0,Math.floor((rect.top+topInset-padY)*sy)),width=Math.min(img.naturalWidth-left,Math.ceil((rect.width+padX*2)*sx)),height=Math.min(img.naturalHeight-top,Math.ceil((rect.height+padY*2)*sy));if(width<160||height<90)return resolve(data);const cv=document.createElement('canvas');cv.width=Math.min(1280,width);cv.height=Math.max(1,Math.round(height*cv.width/width));cv.getContext('2d').drawImage(img,left,top,width,height,0,0,cv.width,cv.height);const out=cv.toDataURL('image/jpeg',.84);resolve(out&&out.length>200?out:data);}catch(_){resolve(data);}};img.onerror=()=>resolve(data);img.src=data;});}
async function cinemaVisionReact(s,token,seq,attempt){if(token!==_cin.token||cinemaSession()!==s||seq!==_cin.visionReactSeq)return false;if(_cin.busy){cinemaSetStatus('画面识别完成 · 等待角色接话…','working','vision');if((attempt||0)<120)setTimeout(()=>cinemaVisionReact(s,token,seq,(attempt||0)+1),500);return false;}const before=(s.items||[]).length;cinemaSetStatus('画面识别完成 · 角色正在回应…','working','vision');await cinemaRoleReply('针对系统刚识别到的当前画面，立刻说一句符合你性格的即时感受；不要复述画面描述，不要剧透，也不要保持沉默。',true,{countActive:false});if(token!==_cin.token||cinemaSession()!==s||seq!==_cin.visionReactSeq)return false;const replied=(s.items||[]).length>before;cinemaSetStatus(replied?'画面识别成功 · 角色已回应':'画面已识别 · 角色回复失败',replied?'ready':'error','vision');if(!replied)toast('画面已经识别成功，但角色回复接口没有返回内容');return replied;}
async function cinemaPlatformScreenFrameData(){
  if(!privateNativeAppOn())throw new Error('网页版不能读取平台播放器画面，请在私人 App 内使用系统取帧识别');
  let status=null;try{status=await window.SmallPhoneNative.request('screenShare.status',{});}catch(_){}
  if(!(status&&status.active)){
    const opened=await window.SmallPhoneNative.request('screenShare.start',{}).catch(()=>null);
    if(!opened)throw new Error('系统屏幕共享面板暂时打不开');
    _cin.platformScreenShare=true;toast('请在系统面板点“开始直播”，随后会自动识别当前画面');
    for(let i=0;i<36;i++){await sleep(i?650:180);try{status=await window.SmallPhoneNative.request('screenShare.status',{});}catch(_){status=null;}if(status&&status.active)break;}
  }
  if(!(status&&status.active))throw new Error('尚未开始系统屏幕共享，请重新点“系统取帧识别”');
  await sleep(450);const frame=await window.SmallPhoneNative.request('screenShare.frame',{}).catch(()=>null),data=String(frame&&frame.dataURL||'');
  if(!data)throw new Error('系统画面还没准备好，请播放后稍等一秒再试');
  return await cinemaCropPlatformFrame(data);
}
async function cinemaAnalyzeFrame(ev,automatic,opt){
  opt=opt||{};
  const platform=!!_cin.provider,v=$('#cinVideo'),s=cinemaSession(),set=cinemaInit().settings,epoch=Number(_cin.visionEpoch||0),token=_cin.token;
  if(platform&&automatic)return false;
  if(automatic&&(!set.visionEnabled||(opt.interval&&!set.autoVision)))return false;
  if(!cinemaVisionConfigured()){if(!automatic)toast('请先配置可用的识图模型');return false;}
  if(!s||(!platform&&(!v||!v.videoWidth))){if(!automatic)toast('先载入视频画面再识别');return false;}
  if(_cin.visionBusy){if(!automatic)toast('当前画面正在识别');return false;}
  const b=ev&&ev.currentTarget,old=b&&b.querySelector('span')&&b.querySelector('span').textContent;
  _cin.visionBusy=true;
  if(b){b.disabled=true;b.classList.add('on');const t=b.querySelector('span');if(t)t.textContent='识别中…';}
  cinemaSetStatus('正在识别当前画面…','working','vision');
  try{
    let data;if(platform)data=await cinemaPlatformScreenFrameData();else{const max=960,scale=Math.min(1,max/v.videoWidth),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(v.videoWidth*scale));cv.height=Math.max(1,Math.round(v.videoHeight*scale));cv.getContext('2d').drawImage(v,0,0,cv.width,cv.height);try{data=cv.toDataURL('image/jpeg',.78);}catch(_){throw new Error('这个在线视频禁止跨域读取画面，只能播放，不能识图');}}
    const desc=cleanReply(await visionAPI(data,'只描述这个影视画面此刻可直接看见的内容、人物和环境，中文1到2句。不要猜后续、不要识别人名、不要评价，不要提图片。如果画面里有清晰可辨的中英文影视字幕，必须原样抄录，并在描述末尾严格写成【字幕：原文】；没有清晰字幕就不要添加这个标记。',{max:240})).replace(/\n+/g,' ').slice(0,320);
    if(token!==_cin.token||cinemaSession()!==s)return false;
    if(automatic&&(epoch!==Number(_cin.visionEpoch||0)||!cinemaInit().settings.visionEnabled)){cinemaSetStatus('画面识别已关闭','ready','vision');return false;}
    if(!desc)throw new Error('没有识别到画面');
    s.sceneDesc=desc;s.sceneAt=cinemaCurrentTime();const visibleSub=(desc.match(/【字幕[:：]\s*([^】]+)】/)||[])[1]||'';if(visibleSub)cinemaApplyVisionSubtitle(visibleSub,s.sceneAt);s.lastVision=s.sceneAt;s.nextVisionAt=s.sceneAt+Math.max(30,+cinemaInit().settings.visionInterval||150);s.visionTrail=Array.isArray(s.visionTrail)?s.visionTrail:[];s.visionTrail.push({at:s.sceneAt,text:desc});if(s.visionTrail.length>24)s.visionTrail=s.visionTrail.slice(-24);s.updatedAt=Date.now();save();
    const reactSeq=(_cin.visionReactSeq||0)+1;_cin.visionReactSeq=reactSeq;
    cinemaSetStatus(opt.silentReply?'画面识别完成':'画面识别完成 · 准备角色回应','ready','vision');
    if(!opt.silentReply)setTimeout(()=>cinemaVisionReact(s,token,reactSeq,0),0);
    return true;
  }catch(e){
    cinemaSetStatus('画面识别失败','error','vision');
    if(!automatic||opt.notice)toast((e&&e.message)||'画面识别失败');
    if(opt.interval){const retry=Math.min(60,Math.max(30,Math.round((+cinemaInit().settings.visionInterval||150)/3))),at=Math.max(0,Number(v&&v.currentTime)||Number(s&&s.progress)||0);if(s)s.nextVisionAt=at+retry;save();const now=Date.now();if(now-Number(_cin.visionErrorAt||0)>30000){_cin.visionErrorAt=now;toast('本次画面识别失败，'+retry+'秒后自动重试：'+((e&&e.message)||'识别失败'));}}
    return false;
  }finally{
    _cin.visionBusy=false;setTimeout(cinemaResumeDeferredStatus,980);
    if(b&&b.isConnected){b.disabled=false;b.classList.remove('on');const t=b.querySelector('span');if(t)t.textContent=old||'识别此帧';}
  }
}
function renderCinemaRead(){const s=cinemaSession(),c=s&&getC(s.cid);if(!s||!c||!_cin.bookPages.length)return `<div class="cinema-home">${nav('放映室')}<div class="cin-empty" style="margin:auto;padding:30px">作品源已失效，请回到放映室重新导入。<button class="btn p" style="margin-top:16px" onclick="back()">返回放映室</button></div></div>`;const i=Math.max(0,Math.min(s.page||0,_cin.bookPages.length-1)),pct=Math.round((i+1)/_cin.bookPages.length*100);
  const set=cinemaInit().settings;return `<div class="cin-reader"><div class="cin-reader-nav"><button onclick="cinemaReaderBack()">‹</button><div><b>${esc(s.title)}</b><span>${cinemaRoleName(c)} 陪读 · ${pct}%</span></div><button id="cinBookVoiceBtn" class="cin-reader-voice ${set.bookVoice?'on':''}" data-cin-action="book-voice" aria-label="${set.bookVoice?'关闭':'开启'}陪读语音">${svgIc(set.bookVoice?'volume':'mute',16)}<small>${set.bookVoice?'出声':'静音'}</small></button><button onclick="cinemaEnd()">结束</button></div><div class="cin-reader-companion"><button id="cinBookCompanionBtn" class="${cinemaCompanionMode()!=='quiet'?'on':''}" data-cin-action="auto">${svgIc('chat',14)}<span>${cinemaCompanionLabel()} · ${cinemaAutoLimit()}条/场</span><i>点这里调整书架陪伴</i></button></div><div id="cinPaperWrap" class="cin-paper-wrap" style="flex-basis:${cinemaReaderPaneHeight()}px"><article class="cin-paper"><div class="cin-page-no">${String(i+1).padStart(2,'0')} / ${String(_cin.bookPages.length).padStart(2,'0')}</div><div class="cin-prose">${esc(_cin.bookPages[i]).replace(/\n/g,'<br>')}</div><div class="cin-page-end">— ${pct}% —</div></article></div>
    <button type="button" class="cin-reader-divider" data-cin-resize="reader" aria-label="上下拖动调整正文和同屏对话的空间"><span></span></button><div class="cin-reader-actions"><button onclick="cinemaBookPage(-1)" ${i<=0?'disabled':''}>上一页</button><button class="comment" onclick="cinemaBookComment()">问问 ${cinemaRoleName(c)}</button><button onclick="cinemaBookPage(1)" ${i>=_cin.bookPages.length-1?'disabled':''}>下一页</button></div><div id="cinLog" class="cin-logbox reader">${cinemaLogHTML(s)}</div><div id="cinBookComposer" class="cin-book-input"><button id="cinBookMic" class="cin-mic ${_cin.micKind==='book'?'recording':''}" data-cin-action="mic" data-kind="book" aria-label="${_cin.micKind==='book'?'持续话筒已开启，点一下关闭':'点一下开启持续话筒'}">${svgIc('mic',17)}</button><textarea id="cinBookInput" rows="3" maxlength="160" placeholder="聊聊刚读到的这一页…"></textarea><button data-cin-action="book-send">发送</button></div></div>`;}
function cinemaAfterReaderRender(){cinemaBindReaderControls();cinemaApplyReaderPaneHeight(cinemaReaderPaneHeight(),false);const inp=$('#cinBookInput');if(inp)inp.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();cinemaSend('book');}});}
function cinemaToggleBookVoice(){const set=cinemaInit().settings;set.bookVoice=!set.bookVoice;save();const b=$('#cinBookVoiceBtn');if(b){b.classList.toggle('on',set.bookVoice);b.setAttribute('aria-label',(set.bookVoice?'关闭':'开启')+'陪读语音');b.innerHTML=svgIc(set.bookVoice?'volume':'mute',16)+'<small>'+(set.bookVoice?'出声':'静音')+'</small>';}toast(set.bookVoice?'陪读时角色会出声':'陪读时角色只发文字');}
function cinemaBookPage(step){const s=cinemaSession(),token=_cin.token;if(!s)return;const old=s.page||0;s.page=Math.max(0,Math.min(_cin.bookPages.length-1,old+step));s.progress=(s.page+1)/_cin.bookPages.length;s.updatedAt=Date.now();const gap=cinemaCompanionMode()==='lively'?2:4;if(step>0&&s.page!==old&&cinemaCanAutoSpeak(s)&&!_cin.busy&&(s.page-(s.lastAutoPage==null?-99:s.lastAutoPage))>=gap){s.lastAutoPage=s.page;setTimeout(()=>{if(token===_cin.token&&cinemaSession()===s)cinemaRoleReply('只根据刚翻到的这一页和你的真实性格判断是否想主动表达；不要使用后文。真有感触就说一句很短的陪读感受，没有明显感触只输出 [保持安静]。',true,{allowSilence:true});},120);}cinemaSaveProgress(true);render();}
function cinemaBookComment(){if(_cin.busy)return;cinemaRoleReply('针对当前这一页，说一句符合你性格的真实感受或观察。不要概括没读到的后文。',false);}
function cinemaReaderBack(){cinemaMicCancel();cinemaSaveProgress(true);back();}
function cinemaWatchedHighlights(s){if(s.kind==='video'){const seen=_cin.cues.filter(x=>x.start<=s.progress),visual=(s.visionTrail||[]).filter(x=>x.at<=s.progress);if(!seen.length&&!visual.length)return'';const step=Math.max(1,Math.ceil(seen.length/10)),lines=seen.filter((_,i)=>i%step===0).slice(-10).map(x=>'['+cinemaFmt(x.start)+'] '+x.text),vstep=Math.max(1,Math.ceil(visual.length/4));visual.filter((_,i)=>i%vstep===0).slice(-4).forEach(x=>lines.push('['+cinemaFmt(x.at)+'] 画面：'+x.text));return lines.join('\n');}const end=Math.min(_cin.bookPages.length,(s.page||0)+1);if(!end)return'';const ids=[0,Math.floor((end-1)/2),end-1].filter((x,i,a)=>a.indexOf(x)===i);return ids.map(i=>'第'+(i+1)+'页：'+(_cin.bookPages[i]||'').slice(0,420)).join('\n');}
function cinemaTranscript(s,c){const items=(s.items||[]).slice(-80).map(x=>(x.who==='me'?summaryUserLabel(c):c.name)+'：'+x.text).join('\n'),high=cinemaWatchedHighlights(s);return '作品：《'+s.title+'》\n形式：'+(s.kind==='book'?'一起阅读':'一起看剧')+(high?'\n已经看到的内容线索：\n'+high:'')+'\n同屏聊天：\n'+(items||'没有额外聊天');}
function cinemaSummaryLength(s){const high=cinemaWatchedHighlights(s),talk=(s.items||[]).map(x=>x&&x.text||'').join(''),evidence=Array.from(high+talk).length;if(evidence<240)return{min:50,max:110};if(evidence<700)return{min:80,max:170};if(evidence<1500)return{min:120,max:230};return{min:150,max:300};}
