function musicNeteaseParse(value){const raw=String(value||'').trim();if(!raw)return null;let id='',type=2,link='',label='';if(/^\d{4,20}$/.test(raw))id=raw;else{const found=raw.match(/https?:\/\/[^\s<>"']+/i);if(!found)return null;link=found[0].replace(/[),，。；;!?！？]+$/,'');let parsed;try{parsed=new URL(link);}catch(_){return null;}const host=String(parsed.hostname||'').toLowerCase().replace(/\.$/,'');if(host!=='music.163.com')return null;const route=parsed.pathname+parsed.search+parsed.hash;if(/\/playlist\b/i.test(route))type=0;else if(/\/album\b/i.test(route))type=1;else if(/\/song\b/i.test(route))type=2;else return null;const match=route.match(/[?&#]id=(\d{4,20})/i)||parsed.pathname.match(/\/(\d{4,20})(?:\/)?$/);id=match&&match[1]||'';label=raw.slice(0,found.index).replace(/(?:分享|单曲|歌单|专辑|网易云音乐|[:：·\-—])+$/g,'').trim().slice(0,50);}if(!/^\d{4,20}$/.test(id))return null;const kind=type===0?'歌单':type===1?'专辑':'歌曲',path=type===0?'playlist':type===1?'album':'song',height=type===2?66:430;return{id,type,kind,label:label||('网易云'+kind+' '+id),storeUrl:'https://music.163.com/#/'+path+'?id='+id,embedUrl:'https://music.163.com/outchain/player?type='+type+'&id='+id+'&auto=0&height='+height,frameHeight:type===2?86:450};}
