async function musicSearchAudius(q){const url=MUSIC_PUBLIC_API+'/tracks/search?query='+encodeURIComponent(q)+'&limit=24&app_name='+encodeURIComponent(MUSIC_PUBLIC_APP),res=await fetchT(url,{method:'GET',headers:{Accept:'application/json'}},20000);if(!res.ok)throw new Error('HTTP '+res.status);const payload=await res.json(),rows=Array.isArray(payload&&payload.data)?payload.data:[];return rows.filter(track=>track&&track.is_available!==false&&track.is_stream_gated!==true&&!track.stream_conditions&&(!track.access||track.access.stream!==false)).map(track=>({provider:'audius',id:musicPublicTrackId(track&&track.id),title:String(track&&track.title||'').trim(),artist:String(track&&track.user&&track.user.name||'').trim(),cover:musicPublicArtwork(track),duration:Math.max(0,+track.duration||0)})).filter(track=>track.id&&track.title).slice(0,12);}
