async function musicSearchRun(){if(_musicSearchBusy)return;musicInit();const input=$('#musicSearchInput'),q=String(input&&input.value||'').trim();if(!q){toast('先输入歌名或歌手');return;}_musicSearchBusy=true;const btn=$('#musicSearchButton'),status=$('#musicSearchStatus');if(btn){btn.disabled=true;btn.textContent='搜索中';}if(status)status.textContent='正在同时搜索大众歌曲和公开曲库…';try{const settled=await Promise.allSettled([musicSearchApple(q),musicSearchAudius(q)]),apple=settled[0].status==='fulfilled'?settled[0].value:[],audius=settled[1].status==='fulfilled'?settled[1].value:[];_musicSearchRows=apple.concat(audius);musicSearchPaint();if(!_musicSearchRows.length&&status)status.textContent='两个在线曲库都没有找到可播放结果';}catch(_){_musicSearchRows=[];if(status)status.textContent='在线曲库暂时连接不上，请稍后再试';if($('#musicSearchResults'))$('#musicSearchResults').innerHTML='';}finally{_musicSearchBusy=false;if(btn){btn.disabled=false;btn.textContent='搜索';}}}
