function musicApplyPackSettings(music){if(!music)return;S.music.loop=!!music.loop;if(music.distance!=null)S.music.distance=music.distance;if(music.meAvatar)S.music.meAvatar=music.meAvatar;if(music.taAvatar)S.music.taAvatar=music.taAvatar;if(music.bg)S.music.bg=music.bg;const discColor=musicDiscColorNormalize(music.discColor);if(discColor){S.music.discColor=discColor;if(discColor.startsWith('#'))S.music.discCustomColor=discColor;}}
async function musicImportSong(raw,audio){if(!raw||typeof raw!=='object')return false;const s=Object.assign({},raw);if(!s.id||S.music.songs.some(x=>x.id===s.id))s.id='m'+uid();let blob=audio||null;if(!blob&&s.file){blob=mDataURLBlob(s.file);delete s.file;}if(blob){const kind=s.mediaKind==='video'||musicVideoLike(blob,s.fileName,s.fileType||blob.type)?'video':'audio',stored=await mPutVerified(s.id,blob,kind);s.src={t:'idb'};s.fileSize=stored.size;s.fileType=stored.type;s.fileSig=stored.sig;s.mediaKind=kind;}else if(s.src&&s.src.t==='idb')return false;else if(!(s.src&&s.src.t==='url'&&s.src.url))return false;S.music.songs.unshift(s);return true;}
async function musicImportPackFile(f){try{musicInit();const binary=await musicBinaryPackRead(f);let n=0,skipped=0;if(binary){const s=Object.assign({},binary.header.music.song);if(!s.fileName&&binary.header.audio&&binary.header.audio.name)s.fileName=binary.header.audio.name;if(await musicImportSong(s,binary.audio))n++;else skipped++;musicApplyPackSettings(binary.header.music);}else{const text=typeof f.text==='function'?await f.text():await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result||''));r.onerror=rej;r.readAsText(f);}),p=JSON.parse(text);if(!p||p.type!=='yibei-music-pack'||!p.music)throw new Error('格式不正确');const incoming=Array.isArray(p.music.songs)?p.music.songs:[];for(const raw of incoming){try{if(await musicImportSong(raw,null))n++;else skipped++;}catch(_){skipped++;}}musicApplyPackSettings(p.music);}save();closeModal();render();toast('已导入 '+n+' 首'+(skipped?'，跳过 '+skipped+' 首不完整歌曲':''));}catch(e){toast((e&&e.message)||'导入失败，文件不对或不完整');}}
